import { createRouter, createWebHistory } from 'vue-router'

const routes = [
  {
    path: '/',
    component: () => import('@/components/Layout/index.vue'),
    redirect: '/dashboard',
    children: [
      { path: 'dashboard', component: () => import('@/views/Dashboard.vue') }, // 数据概览
      { path: 'order', component: () => import('@/views/OrderManage.vue') }, // 订单管理
      { path: 'goods', component: () => import('@/views/GoodsManage.vue') }, // 商品管理
      { path: 'shop', component: () => import('@/views/ShopManage.vue') }, // 门店管理
      { path: 'user', component: () => import('@/views/UserManage.vue') }, // 用户管理
      { path: 'member', component: () => import('@/views/MemberManage.vue') }, // 会员管理
      { path: 'coupon', component: () => import('@/views/CouponManage.vue') }, // 优惠券管理
      { path: 'activity', component: () => import('@/views/ActivityManage.vue') }, // 营销活动
      { path: 'feedback', component: () => import('@/views/Feedback.vue') }, // 留言反馈
      { path: 'system', component: () => import('@/views/SystemSet.vue') }, // 系统设置
    ]
  }
]

const router = createRouter({
  history: createWebHistory(process.env.BASE_URL),
  routes
})

export default router